package org.eclipse.rdf4j.query.algebra.evaluation.function.gql;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.EmptySet;
import org.eclipse.rdf4j.query.algebra.Extension;
import org.eclipse.rdf4j.query.algebra.ExtensionElem;
import org.eclipse.rdf4j.query.algebra.FunctionCall;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategy;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EmptyTripleSource;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class GqlSingleValueFunctionTest {

	private static final String URI = "urn:rdf4j:gql:single-value";
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void isRegisteredAndDeterministic() {
		assertThat(function().getDeterminism()).isEqualTo(Function.Determinism.DETERMINISTIC);
		assertThat(function().mustReturnDifferentResult()).isFalse();
	}

	@Test
	void preservesTheOnlyRdfTermWithoutCoercion() {
		for (Literal sample : new Literal[] { VF.createLiteral("Alice", "en"),
				VF.createLiteral("01", CoreDatatype.XSD.INTEGER), VF.createLiteral("1.00", CoreDatatype.XSD.DECIMAL),
				VF.createLiteral("custom", VF.createIRI("urn:datatype")) }) {
			assertThat(function().evaluate(VF, VF.createLiteral(1L), sample)).isSameAs(sample);
		}
	}

	@Test
	void rejectsMultipleValuesAsAQueryFailure() {
		assertThatThrownBy(() -> function().evaluate(VF, VF.createLiteral(2L), VF.createLiteral("Alice")))
				.isExactlyInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining("multiple");
	}

	@Test
	void doesNotOverflowLargeCounts() {
		Value hugeCount = VF.createLiteral(BigInteger.ONE.shiftLeft(80).add(BigInteger.ONE));
		assertThatThrownBy(() -> function().evaluate(VF, hugeCount, VF.createLiteral("Alice")))
				.isExactlyInstanceOf(QueryEvaluationException.class);
	}

	@Test
	void constantCardinalityFailuresMustNotBecomeExpressionErrors() {
		FunctionCall expression = new FunctionCall(URI, new ValueConstant(VF.createLiteral(2L)),
				new ValueConstant(VF.createLiteral("Alice")));
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		assertThatThrownBy(() -> strategy.evaluate(expression, EmptyBindingSet.getInstance()))
				.isExactlyInstanceOf(QueryEvaluationException.class);
	}

	@Test
	void aConstantFailureIsDeferredUntilAnInputRowIsEvaluated() {
		FunctionCall expression = new FunctionCall(URI, new ValueConstant(VF.createLiteral(2L)),
				new ValueConstant(VF.createLiteral("Alice")));
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		Extension noRows = new Extension(new EmptySet(), new ExtensionElem(expression.clone(), "property"));
		try (var result = strategy.precompile(noRows).evaluate(EmptyBindingSet.getInstance())) {
			assertThat(result.hasNext()).isFalse();
		}
		Extension oneRow = new Extension(new SingletonSet(), new ExtensionElem(expression, "property"));
		var evaluation = strategy.precompile(oneRow);
		assertThatThrownBy(() -> {
			try (var result = evaluation.evaluate(EmptyBindingSet.getInstance())) {
				result.next();
			}
		}).isExactlyInstanceOf(QueryEvaluationException.class);
	}

	@Test
	void constantExpressionErrorsStillProduceUnknown() {
		FunctionCall expression = new FunctionCall(URI, new ValueConstant(VF.createLiteral(0L)),
				new ValueConstant(VF.createLiteral("Alice")));
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		Extension oneRow = new Extension(new SingletonSet(), new ExtensionElem(expression, "property"));
		try (var result = strategy.precompile(oneRow).evaluate(EmptyBindingSet.getInstance())) {
			assertThat(result.hasNext()).isTrue();
			assertThat(result.next().hasBinding("property")).isFalse();
		}
	}

	@Test
	void rejectsEmptyAndNegativeCounts() {
		for (long count : new long[] { 0L, -1L, Long.MIN_VALUE }) {
			assertThatThrownBy(() -> function().evaluate(VF, VF.createLiteral(count), VF.createLiteral("Alice")))
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	@Test
	void rejectsNonIntegerCountsRatherThanTruncatingOrCoercing() {
		for (Value count : new Value[] { VF.createLiteral("1"), VF.createLiteral(1.0),
				VF.createLiteral("1.9", CoreDatatype.XSD.DECIMAL), VF.createLiteral(true), VF.createIRI("urn:one"),
				VF.createLiteral("invalid", CoreDatatype.XSD.INTEGER) }) {
			assertThatThrownBy(() -> function().evaluate(VF, count, VF.createLiteral("Alice")))
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	@Test
	void rejectsMissingArgumentsAndWrongArity() {
		Function function = function();
		assertThatThrownBy(() -> function.evaluate(VF)).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> function.evaluate(VF, VF.createLiteral(1L)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> function.evaluate(VF, VF.createLiteral(1L), VF.createLiteral("x"),
				VF.createLiteral("y"))).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> function.evaluate(VF, null, VF.createLiteral("x")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> function.evaluate(VF, VF.createLiteral(1L), null))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	private static Function function() {
		var function = FunctionRegistry.getInstance().get(URI);
		assertThat(function).as("the GQL scalar-property cardinality function must be registered").isPresent();
		return function.orElseThrow();
	}
}
